//! 🧵️ Original Host source, builtin seed, snapshot, and channel evaluation continuation.
use super::*;
use super::seeds::FlowEvaluationSeeds;
use semio_framework_value::retirement::shared::{SharedControlledRetirement,shared_retirement_birth_bytes,shared_retirement_allocation_bytes};

struct WorkLease<T:RetireOwned+Sync>(Arc<T>);
impl<T:RetireOwned+Sync> RetireOwned for WorkLease<T>{fn retirement(self)->Box<dyn RetirementCursor>{Box::new(SharedControlledRetirement::lease(self.0))}fn retirement_birth_bytes(&self)->Option<usize>{Some(shared_retirement_birth_bytes::<T>())}fn controlled_retirement_supported()->bool{true}}
#[derive(semio_framework_value::RetireOwned)]
struct WorkSources{source:Option<FlowEvaluationSource>,seeds_source:Option<FlowEvaluationSeeds>,tree:Option<Tree>,shared_tree:Option<WorkLease<Tree>>,seeds:Option<HistoryFoldIndex<String,Dictionary>>,shared_seeds:Option<WorkLease<HistoryFoldIndex<String,Dictionary>>>,infos:Option<WorkLease<HistoryFoldIndex<String,OperatorInfo>>>,registry:Option<neural::SharedRegistry>,previous:Option<WorkLease<EvalChannels>>,snapshot:Option<TreeSnapshot>,evaluation:Option<neural::BudgetedEvalState>,channels:Option<EvalChannels>,remaining:Vec<String>,pending:Vec<neural::PendingExtensionEval>,fault:Option<EvalError>}
pub struct FlowEvaluationCompletion{pub snapshot:TreeSnapshot,pub channels:EvalChannels,pub remaining:Vec<String>,pub pending_extensions:Vec<neural::PendingExtensionEval>,pub generation:u64}
/// 🧵️ Owns the original source continuation through every accepted normal and closing event.
pub struct FlowEvaluationWork{sources:ManuallyDrop<Option<WorkSources>>,retirement:Option<ControlledRetirement<WorkSources>>,revision:u64,generation:u64,pub(super) phase:u8,closing:bool,progress:RetainedCloneProgress}
impl FlowEvaluationWork{
 pub fn new(infos:Arc<HistoryFoldIndex<String,OperatorInfo>>,registry:neural::SharedRegistry,previous:Option<Arc<EvalChannels>>,revision:u64,generation:u64)->Self{Self{sources:ManuallyDrop::new(Some(WorkSources{source:Some(FlowEvaluationSource::new()),seeds_source:Some(FlowEvaluationSeeds::new()),tree:None,shared_tree:None,seeds:None,shared_seeds:None,infos:Some(WorkLease(infos)),registry:Some(registry),previous:previous.map(WorkLease),snapshot:None,evaluation:None,channels:None,remaining:Vec::new(),pending:Vec::new(),fault:None})),retirement:None,revision,generation,phase:0,closing:false,progress:Default::default()}}
 pub fn output_was_transferred(&self)->bool{self.phase==255}
 pub fn restore_completion(&mut self,output:FlowEvaluationCompletion){let fields=self.sources.as_mut().unwrap();assert!(fields.snapshot.is_none()&&fields.channels.is_none());fields.snapshot=Some(output.snapshot);fields.channels=Some(output.channels);fields.remaining=output.remaining;fields.pending=output.pending_extensions;self.phase=10;}
 pub fn source_matches(&self,revision:u64,generation:u64)->bool{self.revision==revision&&self.generation==generation}
 pub fn step_progress(&self)->RetainedCloneProgress{self.progress}
 pub fn is_closing(&self)->bool{self.closing}
 pub fn fault(&self)->Option<&EvalError>{self.sources.as_ref()?.fault.as_ref()}
 pub fn next_demands(&self,source:&FlowHostSnapshot,copy:usize)->Result<RetirementDemand,ValueError>{if self.closing{return self.next_close_demands(copy)}let fields=self.sources.as_ref().unwrap();let d=match self.phase{0=>fields.source.as_ref().unwrap().next_demands(source,&fields.infos.as_ref().unwrap().0,copy)?,1=>fields.source.as_ref().unwrap().next_close_demands(copy)?,2=>RetirementDemand{capacity_bytes:shared_retirement_allocation_bytes::<Tree>(),depth:1,..Default::default()},3=>fields.seeds_source.as_ref().unwrap().next_demands(&fields.shared_tree.as_ref().unwrap().0,copy)?,4=>fields.seeds_source.as_ref().unwrap().next_close_demands(copy)?,5=>RetirementDemand{capacity_bytes:shared_retirement_allocation_bytes::<HistoryFoldIndex<String,Dictionary>>(),depth:1,..Default::default()},8=>fields.evaluation.as_ref().unwrap().next_step_demands(copy)?,9=>fields.evaluation.as_ref().unwrap().next_close_demands(copy)?,_=>RetirementDemand{depth:1,..Default::default()}};Ok(d)}
 pub fn step(&mut self,source:&FlowHostSnapshot,budget:EvalStepBudget,grant:RetainedCloneGrant)->Result<Option<FlowEvaluationCompletion>,ValueError>{self.progress=Default::default();let result=self.advance(source,budget,grant);result.map_err(|error|error.with_retained_progress(self.progress))}
 fn advance(&mut self,source:&FlowHostSnapshot,budget:EvalStepBudget,grant:RetainedCloneGrant)->Result<Option<FlowEvaluationCompletion>,ValueError>{if self.closing{return Err(ValueError::literal(ValueRefusalKind::Canceled,"original evaluation Work is closing"))}if grant.maximum_items==0||budget.dispatches==0{return Ok(None)}let d=self.next_demands(source,grant.maximum_copy_bytes)?;if !matches!(self.phase,0|1|3|4|8|9){if grant.maximum_depth<d.depth{return Err(ValueError::literal(ValueRefusalKind::DepthLimit,"original Work exceeds admitted depth"))}if grant.maximum_copy_bytes<d.copy_bytes||grant.maximum_capacity_bytes<d.capacity_bytes||grant.maximum_release_bytes<d.release_bytes{return Ok(None)}}let fields=self.sources.as_mut().unwrap();self.progress.copied_items=1;match self.phase{
  0=>{let child=fields.source.as_mut().unwrap();let result=child.step(source,&fields.infos.as_ref().unwrap().0,grant);self.progress=child.step_progress();if let Some(tree)=result?{fields.tree=Some(tree);child.begin_close();self.phase=1;}},
  1=>{let child=fields.source.as_mut().unwrap();let result=child.close_step(grant);self.progress=child.step_progress();result?;if child.terminal_is_empty(){fields.source=None;self.phase=2;}},
  2=>{let tree=fields.tree.take().unwrap();fields.shared_tree=Some(WorkLease(Arc::new(tree)));self.progress.retained_capacity_bytes=d.capacity_bytes;self.phase=3;},
  3=>{let child=fields.seeds_source.as_mut().unwrap();let result=child.step(&fields.shared_tree.as_ref().unwrap().0,grant);self.progress=child.step_progress();if let Some(seeds)=result?{fields.seeds=Some(seeds);child.begin_close();self.phase=4;}},
  4=>{let child=fields.seeds_source.as_mut().unwrap();let result=child.close_step(grant);self.progress=child.step_progress();result?;if child.terminal_is_empty(){fields.seeds_source=None;self.phase=5;}},
  5=>{let seeds=fields.seeds.take().unwrap();fields.shared_seeds=Some(WorkLease(Arc::new(seeds)));self.progress.retained_capacity_bytes=d.capacity_bytes;self.phase=6;},
  6=>{match TreeSnapshot::capture_retained(fields.shared_tree.as_ref().unwrap().0.clone(),fields.shared_seeds.as_ref().unwrap().0.clone(),grant){Ok((snapshot,p))=>{fields.snapshot=Some(snapshot);self.progress=p;self.phase=7},Err((_error,tree,seeds))=>{drop(tree);drop(seeds);return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original preflighted snapshot handoff refused"))}}},
  7=>{fields.evaluation=Some(neural::BudgetedEvalState::new(fields.shared_tree.take().unwrap().0,fields.shared_seeds.take().unwrap().0,HistoryFoldIndex::new(),fields.infos.take().unwrap().0,fields.registry.take().unwrap(),fields.previous.take().map(|value|value.0)));self.phase=8;},
  8=>{let child=fields.evaluation.as_mut().unwrap();let result=child.step(budget,grant);self.progress=child.normal_step_progress();match result{Ok(neural::BudgetedEvalStep::Working)=>{},Ok(neural::BudgetedEvalStep::Complete(output))=>{fields.channels=Some(output.channels);fields.remaining=output.remaining;fields.pending=output.pending_extensions;child.begin_close();self.phase=9;},Err(error)=>{let kind=if let EvalError::Retained(value)=&error{value.kind}else{ValueRefusalKind::InvalidValue};fields.fault=Some(error);return Err(ValueError::literal(kind,"original retained evaluation fault remains in Work custody"))}}},
  9=>{let child=fields.evaluation.as_mut().unwrap();let result=child.close_step(grant);self.progress=child.normal_step_progress();result?;if child.terminal_is_empty(){fields.evaluation=None;self.phase=10;}},
  10=>{self.phase=255;return Ok(Some(FlowEvaluationCompletion{snapshot:fields.snapshot.take().unwrap(),channels:fields.channels.take().unwrap(),remaining:std::mem::take(&mut fields.remaining),pending_extensions:std::mem::take(&mut fields.pending),generation:self.generation}))},
  _=>return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original Work output was already transferred")),
 }Ok(None)}
 pub fn begin_close(&mut self){self.closing=true;if let Some(fields)=self.sources.as_mut(){if let Some(child)=fields.source.as_mut(){child.begin_close()}if let Some(child)=fields.seeds_source.as_mut(){child.begin_close()}if let Some(child)=fields.evaluation.as_mut(){child.begin_close()}}}
 pub fn next_close_demands(&self,copy:usize)->Result<RetirementDemand,ValueError>{if let Some(owner)=self.retirement.as_ref(){return FlowEvaluationSource::demand(owner,copy)}Ok(RetirementDemand{depth:usize::from(self.sources.is_some()),..Default::default()})}
 pub fn close_step(&mut self,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{self.progress=Default::default();let result=self.close_source(grant);if let Ok(step)=&result{self.progress=step.progress()}result.map_err(|error|error.with_retained_progress(self.progress))}
 fn close_source(&mut self,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{if !self.closing{return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original Work close was not requested"))}if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()))}if grant.maximum_items==0{return Ok(RetainedCloneStep::Progress(Default::default()))}if let Some(owner)=self.retirement.as_mut(){let result=owner.step(grant);self.progress=owner.step_progress();let step=result?;if owner.terminal_is_empty(){self.retirement=None}return Ok(if self.terminal_is_empty(){RetainedCloneStep::Complete(step.progress())}else{RetainedCloneStep::Progress(step.progress())})}if grant.maximum_depth==0{return Err(ValueError::literal(ValueRefusalKind::DepthLimit,"original Work closure requires admitted depth"))}self.retirement=Some(ControlledRetirement::new(self.sources.take().unwrap()).unwrap_or_else(|_|unreachable!()));Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,..Default::default()}))}
 pub fn terminal_is_empty(&self)->bool{self.closing&&self.sources.is_none()&&self.retirement.is_none()}
}
impl Drop for FlowEvaluationWork{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original evaluation Work must reach explicit terminal custody");if self.terminal_is_empty(){unsafe{ManuallyDrop::drop(&mut self.sources)}}}}
struct WorkRetirement(FlowEvaluationWork);
impl RetirementCursor for WorkRetirement{
 fn close_step(&mut self,grant:RetainedCloneGrant)->RetirementStep{match self.0.close_step(grant){Ok(step)if step.progress()!=RetainedCloneProgress::default()=>RetirementStep::Progress(step.progress()),Ok(RetainedCloneStep::Complete(_))=>RetirementStep::Complete,Ok(_)=>RetirementStep::BudgetExhausted,Err(error)=>RetirementStep::Failure(error)}}
 fn terminal_is_empty(&self)->bool{self.0.terminal_is_empty()}
 fn next_work_byte_demand(&self)->Result<usize,ValueError>{Ok(self.0.next_close_demands(0)?.copy_bytes)}
 fn allows_admitted_narrow_work(&self)->bool{true}
 fn next_birth_bytes(&self,copy:usize)->Option<usize>{self.0.next_close_demands(copy).ok().map(|d|d.capacity_bytes)}
 fn next_close_byte_demand(&self)->Option<usize>{self.0.next_close_demands(0).ok().map(|d|d.release_bytes)}
 fn next_depth_demand(&self)->Result<usize,ValueError>{Ok(self.0.next_close_demands(0)?.depth)}
 fn terminal_release_bytes(&self)->Option<usize>{self.terminal_is_empty().then_some(size_of::<Self>())}
}
impl RetireOwned for FlowEvaluationWork{fn retirement(mut self)->Box<dyn RetirementCursor>{self.begin_close();Box::new(WorkRetirement(self))}fn retirement_birth_bytes(&self)->Option<usize>{Some(size_of::<WorkRetirement>())}fn controlled_retirement_supported()->bool{true}}
